);

export enum ClassType {
  LIVE = 'LIVE WORKSHOP',
  RECORDED = 'MASTERCLASS RECORDED'
}

export interface CulinaryClass {
  id: string;
  title: string;
  description: string;
  price: number;
  image: string;
  type: ClassType;
  duration: string;
  level: 'Beginner' | 'Professional' | 'Executive';
