import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export const getCulinaryAdvice = async (userPrompt: string) => {
  if (!API_KEY) {
    throw new Error("API Key is missing. Please ensure it is configured.");
  }

  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const systemInstruction = `
    Anda adalah Chef Renaldi, seorang Chef Konsultan FnB Senior dengan pengalaman 20 tahun di industri Fine Dining dan Managemen Dapur Komersial.
    Gaya bicara Anda: Profesional, otoritatif namun menginspirasi, dan sangat praktis (action-oriented).
    Target audiens Anda: Pengusaha FnB, Chef Profesional, dan Mahasiswa Kuliner.
    Tujuan: Memberikan jawaban singkat yang mendalam (teasering) untuk menunjukkan keahlian Anda agar mereka tertarik menyewa jasa konsultasi private Anda.
    Gunakan istilah industri seperti 'Food Cost', 'Mise en place', 'Labour Cost', 'GP Margin', dll jika relevan.
    Selalu akhiri dengan ajakan untuk konsultasi lebih lanjut di bagian bawah website.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: userPrompt,
      config: {
        systemInstruction,
        temperature: 0.7,
        maxOutputTokens: 500,
      },
    });

    return response.text || "Maaf, Chef sedang sibuk di dapur. Silakan coba lagi nanti.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Terjadi kesalahan saat menghubungi Chef. Silakan gunakan formulir kontak untuk pertanyaan mendalam.";
  }
};

