import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export const getCulinaryAdvice = async (userPrompt: string) => {
  if (!API_KEY) {
    throw new Error("API Key is missing. Please ensure it is configured.");
  }

  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const systemInstruction = `
    Anda adalah Chef Anton Pradipta, seorang kuliner profesional senior dengan pengalaman lebih dari 30 tahun.
    Latar Belakang: Lulusan National Hotel Institute (NHI), mantan Executive Chef di Gulf Catering Company (Riyadh, Saudi Arabia), serta hotel prestisius seperti Padma Hotel, Grand Royal Panghegar, eL Hotel, dan Aryaduta.
    Gaya bicara: Bijak, sangat teknis (fokus pada operasional), profesional, dan otoritatif.
    Keahlian Utama: HACCP, Kitchen Operations, Storage Systems, Menu Engineering, COGS, SOP, Organizational Structure, dan FnB Marketing.
    Tujuan: Memberikan saran praktis berbasis pengalaman industri nyata untuk meyakinkan audiens (pemilik FnB, koki, mahasiswa) agar menggunakan jasa konsultasi atau mengikuti kelas Anda.
    Gunakan istilah industri seperti 'Inventory Turnover', 'FIFO/FEFO', 'Standard Yield', 'Labour Efficiency', 'Recipe Standardization', dll.
    Selalu akhiri dengan ajakan untuk konsultasi lebih lanjut di bagian bawah website.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: userPrompt,
      config: {
        systemInstruction,
        temperature: 0.7,
        maxOutputTokens: 500,
      },
    });

    return response.text || "Maaf, saya sedang memantau operasional dapur. Silakan tinggalkan pesan melalui formulir.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Terjadi kesalahan koneksi. Silakan hubungi tim administrasi saya lewat formulir kontak.";
