import { GoogleGenAI } from "@google/genai";

export const generatePortfolioImage = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const basePrompt = "A high-quality professional photography of an Indonesian senior executive chef, resembling Chef Anton Pradipta. He has a friendly smiling face, middle-aged. He is wearing a tall professional white chef hat (toque blanche) and a clean white chef coat with distinct orange batik patterns on the collar and cuffs. ";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: basePrompt + prompt + " Cinematic lighting, depth of field, 4k resolution, realistic textures.",
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        },
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data returned from Gemini");
  } catch (error) {
    console.error("Image Generation Error:", error);
    throw error;
  }
};

import { GoogleGenAI } from "@google/genai";

export const generatePortfolioImage = async (prompt: string): Promise<string> => {
  // Always create a new instance right before the call to ensure fresh API key/context
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Detailed description based on the provided photos: 
  // Middle-aged Indonesian chef, smiling, tall toque blanche hat, white coat with orange batik accents.
  const basePrompt = "Professional food and portrait photography. Featuring a middle-aged Indonesian male Executive Chef (Chef Anton Pradipta) with a friendly smile and short greyish-black beard. He is wearing a tall professional white chef hat and a clean white chef uniform that has distinct orange batik patterns on the collar and cuffs. ";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: `${basePrompt} ${prompt}. The setting is professional, cinematic lighting, shallow depth of field, high resolution 4k, realistic textures.`,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        },
      },
    });

    // Iterate through parts to find the image data, as response might include text parts
    if (response.candidates && response.candidates[0].content.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found in response parts.");
  } catch (error) {
    console.error("Image Generation Error:", error);
    // Fallback to a themed placeholder if AI fails
    return `https://picsum.photos/seed/${encodeURIComponent(prompt)}/800/800`;
  }
};

