export const generatePortfolioImage = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Prompt disesuaikan dengan foto asli: Chef Indonesia, batik oranye di kerah/lengan, topi tinggi.
  const basePrompt = "Professional high-end culinary photography. Featuring an Indonesian male Executive Chef (Chef Anton Pradipta), middle-aged, friendly and authoritative smile. He is wearing a clean white professional chef uniform with distinctive orange batik patterns on the collar and cuffs, and a very tall white chef hat (toque blanche). ";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: `${basePrompt} ${prompt}. Scene: Cinematic lighting, luxury kitchen environment, bokeh background, 8k resolution, realistic textures.`,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        },
      },
    });

    if (response.candidates && response.candidates[0].content.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found.");
  } catch (error) {
    console.error("Image Generation Error:", error);
    return `https://picsum.photos/seed/${encodeURIComponent(prompt)}/800/800`;
  }
};

