  // Simplified prompt to avoid safety triggers related to specific real-world names
  // Focus on descriptors: "Indonesian male executive chef", "orange batik", "tall chef hat"
  const basePrompt = `
    PHOTOREALISTIC 8K. Close-up portrait of a professional Indonesian male Executive Chef, 
    middle-aged, charismatic and professional friendly smile. 
