    const initImages = async () => {
      // 1. Generate main profile image
      try {
        const url = await generateChefImage("Smiling warmly, holding a professional culinary manual, luxury hotel kitchen background, focus on orange batik detail");
        setProfileImg(url);
      } catch (err) {
        console.warn("Main profile image generation failed");
      }

      // 2. Generate portfolio images sequentially to avoid 429 rate limits
      for (const item of PORTFOLIO) {
        try {
          const url = await generatePortfolioImage(item.aiPrompt);
          setPortfolioImgs(prev => ({ ...prev, [item.id]: url }));
          // Small delay between requests to be extra safe with rate limits
          await new Promise(r => setTimeout(r, 500));
        } catch (err) {
          console.warn(`Portfolio image generation failed for ${item.id}`);
        }
      }
    };

    initImages();
  }, []);

