          </div>

          <div className="hidden lg:flex space-x-8">
            {NAV_ITEMS.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className="text-xs font-bold uppercase tracking-widest text-slate-500 hover:text-gold transition-colors duration-200"
                onClick={(e) => {
                  if (item.label === 'Home' && onHomeClick) {
