                            newList[idx].name = e.target.value;
                            setData({...data, reviews: newList});
                          }}
                        />
                        <input 
                          type="text" 
                          className="bg-transparent border-none text-[10px] font-black uppercase tracking-widest text-gold p-0 focus:ring-0 w-full" 
                          value={rev.role}
