export const getCMSData = (): CMSData => {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved) {
    try {
      const parsed = JSON.parse(saved);
      // Migration for new Hero CTA fields if they don't exist
      if (!parsed.heroCTA_Workshop_Title) {
        parsed.heroCTA_Workshop_Title = DEFAULT_DATA.heroCTA_Workshop_Title;
        parsed.heroCTA_Workshop_Desc = DEFAULT_DATA.heroCTA_Workshop_Desc;
        parsed.heroCTA_Recorded_Title = DEFAULT_DATA.heroCTA_Recorded_Title;
        parsed.heroCTA_Recorded_Desc = DEFAULT_DATA.heroCTA_Recorded_Desc;
        parsed.heroCTA_Consultancy_Title = DEFAULT_DATA.heroCTA_Consultancy_Title;
        parsed.heroCTA_Consultancy_Desc = DEFAULT_DATA.heroCTA_Consultancy_Desc;
      }
      return parsed;
    } catch (e) {
      return DEFAULT_DATA;
    }
  }
  return DEFAULT_DATA;
};

export const saveCMSData = (data: CMSData) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

export const resetToDefault = () => {
  localStorage.removeItem(STORAGE_KEY);
  window.location.reload();
};

