        {/* Profile Detail */}
        <section className="py-32 bg-white overflow-hidden">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-20 items-center">
              <div className="relative">
                <div className="absolute -top-10 -left-10 w-48 h-48 bg-orange-100 rounded-full blur-3xl opacity-50"></div>
                <div className="relative aspect-[4/5] rounded-[4rem] overflow-hidden shadow-2xl border-4 border-white bg-slate-50">
                  <img src={cmsData.chefProfileImage} alt="Chef Profile" className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-orange-950/30 via-transparent to-transparent"></div>
                </div>
                <div className="absolute -bottom-10 -right-10 bg-slate-900 p-10 rounded-[3rem] shadow-2xl text-white hidden lg:block max-w-xs rotate-2 border-r-8 border-gold">
                  <p className="font-serif text-4xl mb-2 font-black text-gold">30+</p>
                  <p className="text-[10px] uppercase tracking-[0.2em] font-black opacity-70 leading-relaxed">Culinary Mastery Years</p>
                </div>
              </div>

              <div className="relative">
                <span className="text-orange-600 font-black uppercase tracking-[0.3em] text-[10px] mb-6 block flex items-center gap-4">
                  <span className="w-12 h-px bg-orange-600"></span> Maestro of Operations
                </span>
                <h2 className="text-4xl md:text-6xl font-serif text-slate-900 mb-10 leading-tight">{cmsData.chefName}</h2>
                <p className="font-serif italic text-slate-900 border-l-4 border-orange-500 pl-8 text-2xl mb-8">"{cmsData.chefBioQuote}"</p>
                <p className="text-slate-500 leading-relaxed text-lg mb-10">{cmsData.chefBio}</p>
              </div>
            </div>
          </div>
        </section>

        <Partners partners={cmsData.partners} />

        <Reviews customReviews={cmsData.reviews} />
      </div>

      {/* --- LIVE WORKSHOP --- */}
      <section id="live-workshops" className="py-32 bg-white scroll-mt-20 border-t border-stone-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
