export const getCMSData = (): CMSData => {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved) {
    try {
      const parsed = JSON.parse(saved);
      // Migration: If version mismatch or missing data, merge or reset
      if (parsed.version !== DATA_VERSION || !parsed.workshops || parsed.workshops.length === 0) {
        // For development/demo, we reset if data is old/broken
        return DEFAULT_DATA;
      }
      return parsed;
    } catch (e) {
      return DEFAULT_DATA;
    }
  }
  return DEFAULT_DATA;
};

export const saveCMSData = (data: CMSData) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...data, version: DATA_VERSION }));
};

export const resetToDefault = () => {
  localStorage.removeItem(STORAGE_KEY);
  window.location.reload();
};

