const FileUploader = ({ label, guidance, onUpload }: { label: string, guidance: string, onUpload: (base64: string) => void }) => {
  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => onUpload(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-3">
      <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">{label}</label>
      <div className="flex flex-col gap-2">
        <input 
          type="file" 
          accept="image/*"
          className="w-full text-[10px] text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-[10px] file:font-black file:uppercase file:bg-gold file:text-white hover:file:bg-slate-900 transition-all cursor-pointer"
          onChange={handleFile}
        />
        {guidance && (
          <div className="p-3 bg-blue-50/50 rounded-xl border border-blue-100/50">
            <p className="text-[8px] text-blue-500">{guidance}</p>
          </div>
        )}
      </div>
    </div>
  );
};

const AdminCMS: React.FC<Props> = ({ onExit }) => {
  const [data, setData] = useState<CMSData>(getCMSData());
  const [activeTab, setActiveTab] = useState<'hero' | 'profile' | 'partners' | 'workshops' | 'recorded' | 'portfolio' | 'reviews'>('hero');
  const [isSaved, setIsSaved] = useState(false);

  const handleSave = () => {
    saveCMSData(data);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const updateField = (field: keyof CMSData, value: any) => {
    setData(prev => ({ ...prev, [field]: value }));
  };

  const updateListItem = (field: keyof CMSData, id: string, updates: any) => {
    setData(prev => ({
      ...prev,
      [field]: (prev[field] as any[]).map(item => item.id === id ? { ...item, ...updates } : item)
    }));
  };

  const addItem = (field: keyof CMSData, newItem: any) => {
    setData(prev => ({
      ...prev,
      [field]: [newItem, ...(prev[field] as any[])]
    }));
  };

  const removeItem = (field: keyof CMSData, id: string) => {
    setData(prev => ({
      ...prev,
      [field]: (prev[field] as any[]).filter(item => item.id !== id)
    }));
  };

  // Logic to separate active and historical in the CMS UI
  const workshops = useMemo(() => {
    return {
      active: data.workshops.filter(ws => !ws.isHistorical),
      historical: data.workshops.filter(ws => ws.isHistorical)
    };
  }, [data.workshops]);

  return (
    <div className="min-h-screen bg-stone-50 flex font-sans">
      {/* Sidebar */}
      <div className="w-72 bg-slate-950 text-white flex flex-col shadow-2xl z-20">
        <div className="p-10 border-b border-white/5">
          <h1 className="text-2xl font-serif font-black text-gold uppercase tracking-tighter">Chef Portal</h1>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.3em] mt-2">CMS Management</p>
        </div>

        <nav className="flex-grow p-6 space-y-1">
          {[
            { id: 'hero', label: 'Landing Hero', icon: '✨' },
            { id: 'profile', label: 'Chef Profile', icon: '👤' },
            { id: 'partners', label: 'Partners', icon: '🤝' },
            { id: 'workshops', label: 'Workshops', icon: '🎥' },
            { id: 'recorded', label: 'Academy', icon: '📀' },
            { id: 'portfolio', label: 'Portfolio', icon: '🖼️' },
            { id: 'reviews', label: 'Reviews', icon: '⭐️' },
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${
                activeTab === tab.id 
                  ? 'bg-gold text-white shadow-lg translate-x-2' 
                  : 'text-slate-500 hover:text-white hover:bg-white/5'
              }`}
            >
              <span>{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-white/5 space-y-3">
          <button onClick={resetToDefault} className="w-full py-4 text-[10px] font-black uppercase text-red-400 hover:bg-red-400/10 rounded-xl transition-all">Reset Factory</button>
          <button onClick={onExit} className="w-full py-4 bg-white text-slate-950 text-[10px] font-black uppercase rounded-xl hover:bg-gold transition-all">Exit to Website</button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-grow flex flex-col h-screen overflow-hidden">
        <header className="bg-white/80 backdrop-blur-md border-b border-stone-200 h-24 flex items-center justify-between px-12">
          <h2 className="text-xl font-serif font-black text-slate-900 uppercase tracking-widest">{activeTab}</h2>
          <div className="flex items-center gap-6">
            {isSaved && <span className="text-green-600 text-[10px] font-black uppercase tracking-widest animate-pulse">Saved Successfully</span>}
            <button onClick={handleSave} className="px-10 py-4 bg-slate-900 text-white text-[11px] font-black uppercase rounded-full hover:bg-gold transition-all shadow-xl">Publish Updates</button>
          </div>
        </header>

        <main className="p-12 overflow-y-auto flex-grow">
          <div className="max-w-5xl mx-auto space-y-12">

            {activeTab === 'hero' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-10 rounded-[3rem] border border-stone-200 space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Hero Main Title</label>
                    <input type="text" className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-4 text-sm font-bold" value={data.heroTitle} onChange={(e) => updateField('heroTitle', e.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Description</label>
                    <textarea className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-4 text-sm h-32" value={data.heroSubtitle} onChange={(e) => updateField('heroSubtitle', e.target.value)} />
                  </div>
                </div>
                <div className="bg-white p-10 rounded-[3rem] border border-stone-200 flex flex-col items-center">
                  <div className="aspect-[3/4] w-48 rounded-3xl overflow-hidden shadow-2xl mb-6">
                    <img src={data.heroImage} className="w-full h-full object-cover" alt="" />
                  </div>
                  <FileUploader label="Update Hero Image" guidance="Portrait 3:4 recommended." onUpload={(b) => updateField('heroImage', b)} />
                </div>
              </div>
            )}

            {activeTab === 'workshops' && (
              <div className="space-y-12">
                <div className="flex justify-between items-center">
                  <h3 className="text-sm font-black uppercase tracking-widest text-gold">Active Workshops</h3>
                  <button 
                    onClick={() => addItem('workshops', { 
                      id: `ws-${Date.now()}`, 
                      title: 'New Workshop Batch', 
                      description: 'Intensive session...', 
                      price: 1500000, 
                      location: 'Zoom / Offline', 
                      image: 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?q=80&w=800', 
                      type: ClassType.LIVE, 
                      duration: '4 Hours', 
                      level: 'Professional', 
                      date: new Date(Date.now() + 86400000 * 7).toISOString().slice(0, 16), 
                      isHistorical: false 
                    })} 
                    className="px-6 py-3 bg-slate-900 text-white text-[10px] font-black uppercase rounded-full"
                  >
                    + Add New Batch
                  </button>
                </div>

                <div className="space-y-6">
                  {workshops.active.map(ws => (
                    <div key={ws.id} className="bg-white p-8 rounded-[3rem] border border-stone-200 flex flex-col md:flex-row gap-8">
                      <div className="w-40 h-40 rounded-3xl overflow-hidden bg-stone-100 flex-shrink-0">
                        <img src={ws.image} className="w-full h-full object-cover" alt="" />
                      </div>
                      <div className="flex-grow space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <input className="text-lg font-serif font-black bg-stone-50 rounded p-2" value={ws.title} onChange={(e) => updateListItem('workshops', ws.id, { title: e.target.value })} />
                          <input type="datetime-local" className="text-xs bg-stone-50 rounded p-2" value={ws.date ? ws.date.slice(0, 16) : ''} onChange={(e) => updateListItem('workshops', ws.id, { date: e.target.value })} />
                        </div>
                        <div className="grid grid-cols-3 gap-4">
                           <input type="number" placeholder="Price" className="text-xs bg-stone-50 rounded p-2" value={ws.price || 0} onChange={(e) => updateListItem('workshops', ws.id, { price: Number(e.target.value) })} />
                           <input placeholder="Location" className="text-xs bg-stone-50 rounded p-2" value={ws.location || ''} onChange={(e) => updateListItem('workshops', ws.id, { location: e.target.value })} />
                           <button onClick={() => updateListItem('workshops', ws.id, { isHistorical: true })} className="text-[9px] font-black uppercase text-gold hover:underline">Move to Historical</button>
                        </div>
                        <FileUploader label="" guidance="" onUpload={(b) => updateListItem('workshops', ws.id, { image: b })} />
                        <button onClick={() => removeItem('workshops', ws.id)} className="text-[9px] font-black uppercase text-red-500">Remove</button>
                      </div>
                    </div>
                  ))}
                  {workshops.active.length === 0 && <p className="text-slate-400 text-center py-10 italic">No active workshops. Add one to show on website.</p>}
                </div>

                <div className="pt-12 border-t border-stone-200">
                  <h3 className="text-sm font-black uppercase tracking-widest text-slate-400 mb-6">Historical Archives</h3>
                  <div className="space-y-6">
                    {workshops.historical.map(ws => (
                      <div key={ws.id} className="bg-white/60 p-6 rounded-[2.5rem] border border-stone-100 flex gap-6 grayscale hover:grayscale-0 transition-all">
                        <div className="w-24 h-24 rounded-2xl overflow-hidden flex-shrink-0">
                          <img src={ws.image} className="w-full h-full object-cover" alt="" />
                        </div>
                        <div className="flex-grow">
                          <h4 className="font-serif font-bold">{ws.title}</h4>
                          <p className="text-[10px] text-slate-400">{ws.location} • {ws.realAttendance || 0} Alumni</p>
                          <div className="mt-2 flex gap-4">
                             <button onClick={() => updateListItem('workshops', ws.id, { isHistorical: false })} className="text-[8px] font-black uppercase text-blue-500">Restore to Active</button>
                             <button onClick={() => removeItem('workshops', ws.id)} className="text-[8px] font-black uppercase text-red-500">Delete Permanently</button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* ... other tabs would go here similarly ... */}
            {activeTab !== 'hero' && activeTab !== 'workshops' && (
              <div className="bg-stone-50 p-20 rounded-[4rem] text-center border border-dashed border-stone-200">
                <p className="text-slate-400 italic">This tab is currently under development or maintenance. Workshop & Hero are active.</p>
              </div>
            )}

          </div>
        </main>
      </div>
    </div>
  );
};

export default AdminCMS;

import React, { useState, useEffect, useMemo } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Partners from './components/Partners';
import Reviews from './components/Reviews';
import ClassCard from './components/ClassCard';
import AICulinaryAssistant from './components/AICulinaryAssistant';
import Footer from './components/Footer';
import LiveWorkshopDetail from './pages/LiveWorkshopDetail';
import RecordedClassDetail from './pages/RecordedClassDetail';
import ConsultancyDetail from './pages/ConsultancyDetail';
import { getCMSData, CMSData } from './services/dataService';

const App: React.FC = () => {
  const [cmsData, setCmsData] = useState<CMSData>(getCMSData());
  const [currentPage, setCurrentPage] = useState<'home' | 'workshop-detail' | 'recorded-detail' | 'consultancy-detail'>('home');
  const [selectedWorkshopId, setSelectedWorkshopId] = useState<string | null>(null);

  useEffect(() => {
    const data = getCMSData();
    setCmsData(data);
  }, [currentPage]);

  const workshopsData = useMemo(() => {
    const now = new Date();
    const processed = [...cmsData.workshops].map(ws => {
      if (ws.date && !ws.isHistorical) {
        const wsDate = new Date(ws.date);
        if (wsDate < now) return { ...ws, isHistorical: true };
      }
      return ws;
    });

    return {
      active: processed.filter(ws => !ws.isHistorical),
      historical: processed.filter(ws => ws.isHistorical)
    };
  }, [cmsData.workshops]);

  const selectedWorkshop = useMemo(() => {
    if (!selectedWorkshopId) return null;
    return cmsData.workshops.find(w => w.id === selectedWorkshopId);
  }, [cmsData.workshops, selectedWorkshopId]);

  const handleViewWorkshopDetail = (id: string) => {
    setSelectedWorkshopId(id);
    setCurrentPage('workshop-detail');
    window.scrollTo({ top: 0, behavior: 'instant' });
  };

  const goToHome = () => {
    setCurrentPage('home');
    setSelectedWorkshopId(null);
  };

  const handleNavWorkshopClick = () => {
    if (currentPage !== 'home') {
      goToHome();
      // Use longer timeout for smoother transition to home view before scrolling
      setTimeout(() => {
        const el = document.getElementById('live-workshops');
        if (el) el.scrollIntoView({ behavior: 'smooth' });
      }, 200);
    } else {
      const el = document.getElementById('live-workshops');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const commonNavProps = {
    onHomeClick: goToHome,
    onWorkshopClick: handleNavWorkshopClick,
    onRecordedClick: () => {
      setCurrentPage('recorded-detail');
      window.scrollTo({ top: 0, behavior: 'instant' });
    },
    onConsultancyClick: () => {
      setCurrentPage('consultancy-detail');
      window.scrollTo({ top: 0, behavior: 'instant' });
    }
  };

  if (currentPage === 'workshop-detail' && selectedWorkshop) {
    return (
      <div className="min-h-screen bg-white">
        <Navbar {...commonNavProps} />
        <LiveWorkshopDetail workshop={selectedWorkshop} onBack={goToHome} />
        <Footer />
      </div>
    );
  }

  if (currentPage === 'recorded-detail') {
    return (
      <div className="min-h-screen bg-white">
        <Navbar {...commonNavProps} />
        <RecordedClassDetail onBack={goToHome} />
        <Footer />
      </div>
    );
  }

  if (currentPage === 'consultancy-detail') {
    return (
      <div className="min-h-screen bg-white">
        <Navbar {...commonNavProps} />
        <ConsultancyDetail onBack={goToHome} />
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white selection:bg-gold/30">
      <Navbar {...commonNavProps} />

      <div id="home" className="scroll-mt-20">
        <Hero 
          cmsData={cmsData}
          onWorkshopClick={handleNavWorkshopClick} 
          onRecordedClick={commonNavProps.onRecordedClick}
          onConsultancyClick={commonNavProps.onConsultancyClick}
        />

        {/* Chef Bio */}
        <section className="py-32 bg-white overflow-hidden">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-20 items-center">
              <div className="relative">
                <div className="absolute -top-10 -left-10 w-48 h-48 bg-orange-100 rounded-full blur-3xl opacity-40"></div>
                <div className="relative aspect-[4/5] rounded-[4rem] overflow-hidden shadow-2xl border-4 border-white bg-slate-50">
                  <img src={cmsData.chefProfileImage} alt="Chef" className="w-full h-full object-cover" />
                </div>
              </div>
              <div className="relative">
                <span className="text-orange-600 font-black uppercase tracking-[0.3em] text-[10px] mb-6 block">Maestro of Operations</span>
                <h2 className="text-5xl md:text-6xl font-serif text-slate-900 mb-10 leading-tight">{cmsData.chefName}</h2>
                <p className="font-serif italic text-slate-900 border-l-4 border-orange-500 pl-8 text-2xl mb-8 leading-relaxed">"{cmsData.chefBioQuote}"</p>
                <p className="text-slate-500 leading-relaxed text-lg">{cmsData.chefBio}</p>
              </div>
            </div>
          </div>
        </section>

        <Partners partners={cmsData.partners} />
        <Reviews customReviews={cmsData.reviews} />
      </div>

      {/* --- LIVE WORKSHOP SECTION --- */}
      <section id="live-workshops" className="py-32 bg-white scroll-mt-20 border-t border-stone-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col md:flex-row md:items-end justify-between mb-20 gap-8 text-center md:text-left">
            <div>
              <span className="text-gold font-black uppercase tracking-[0.3em] text-[10px] mb-4 block">Enrollment Ongoing</span>
              <h2 className="text-5xl md:text-6xl font-serif text-slate-900">Live Professional Workshops</h2>
              <p className="mt-4 text-slate-400 italic text-lg">"Belajar langsung dengan simulasi operasional nyata."</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
            {workshopsData.active.length > 0 ? (
              workshopsData.active.map(item => (
                <ClassCard key={item.id} item={item} onViewDetail={handleViewWorkshopDetail} />
              ))
            ) : (
              <div className="col-span-full py-20 px-10 bg-stone-50 rounded-[4rem] border-4 border-dashed border-stone-100 flex flex-col items-center text-center">
                <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-4xl shadow-xl mb-8">⏳</div>
                <h3 className="text-2xl font-serif text-slate-900 mb-4">Belum Ada Sesi Aktif Terdekat</h3>
                <p className="text-slate-500 max-w-md mb-10">Saat ini Chef Anton sedang memantau operasional di lapangan. Sambil menunggu jadwal baru, Anda dapat mengeksplorasi opsi berikut:</p>

                <div className="flex flex-col sm:flex-row gap-6">
                  <button 
                    onClick={commonNavProps.onRecordedClick}
                    className="px-8 py-4 bg-gold text-white text-[10px] font-black uppercase tracking-widest rounded-2xl hover:bg-slate-900 transition-all shadow-xl"
                  >
                    Beli Kelas Rekaman
                  </button>
                  <button 
                    onClick={commonNavProps.onConsultancyClick}
                    className="px-8 py-4 bg-slate-900 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl hover:bg-gold transition-all shadow-xl"
                  >
                    Private Konsultasi
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </section>

      {/* --- RECORDED CLASSES --- */}
      <section id="recorded-classes" className="py-32 bg-slate-950 text-white relative rounded-[5rem] mx-4 mb-32 overflow-hidden shadow-2xl scroll-mt-20">
        <div className="absolute inset-0 opacity-10 dot-pattern-gold pointer-events-none"></div>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <div className="flex flex-col md:flex-row items-center justify-between mb-20 gap-10">
            <div>
              <span className="text-gold font-black uppercase tracking-[0.3em] text-[10px] mb-4 block">Academy Access</span>
              <h2 className="text-4xl md:text-6xl font-serif mb-6">Video Masterclass Academy</h2>
              <p className="text-slate-400 text-lg max-w-xl">Kuasai standar bintang lima secara mandiri.</p>
            </div>
            <button onClick={commonNavProps.onRecordedClick} className="bg-gold text-white px-10 py-5 rounded-[2rem] font-black uppercase tracking-widest text-xs shadow-xl">Katalog Lengkap</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
            {cmsData.recordedClasses.slice(0, 4).map(item => <ClassCard key={item.id} item={item} />)}
          </div>
        </div>
      </section>

      {/* --- HISTORICAL WORKSHOPS --- */}
      {workshopsData.historical.length > 0 && (
        <section className="py-32 bg-stone-50 border-t border-stone-100">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-24">
              <span className="text-gold font-black uppercase tracking-[0.4em] text-[10px] mb-4 block">Our Legacy</span>
              <h2 className="text-5xl font-serif text-slate-900">Workshop Sebelumnya</h2>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              {workshopsData.historical.map(pw => (
                <div key={pw.id} onClick={() => handleViewWorkshopDetail(pw.id)} className="group bg-white rounded-[4rem] border border-stone-100 p-8 flex gap-8 items-center hover:shadow-2xl cursor-pointer transition-all">
                  <div className="w-40 h-40 rounded-[2.5rem] overflow-hidden flex-shrink-0">
                    <img src={pw.image} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all" alt="" />
                  </div>
                  <div>
                    <h3 className="text-2xl font-serif text-slate-900 group-hover:text-gold transition-colors">{pw.title}</h3>
                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mt-2">{pw.displayDate}</p>
                    <span className="inline-block mt-4 text-[9px] font-black uppercase text-gold px-4 py-2 bg-gold/5 rounded-full border border-gold/10">
                      {pw.realAttendance || 0} Alumni Terdaftar
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* --- CONSULTATION --- */}
      <div id="consultancy" className="scroll-mt-20 bg-white pb-32">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-24">
           <AICulinaryAssistant />
        </div>
        <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="bg-stone-50 rounded-[5rem] p-10 md:p-24 border border-stone-100 flex flex-col lg:flex-row gap-20 items-center">
             <div className="flex-grow">
               <span className="text-orange-600 font-black uppercase tracking-widest text-[10px] mb-6 block">Professional Strategy</span>
               <h2 className="text-5xl md:text-6xl font-serif mb-8 leading-tight">Private Executive Consultancy</h2>
               <p className="text-slate-500 max-w-lg mb-12 text-xl italic">"Transformasi operasional bisnis FnB Anda dengan standar akurasi industri hotel bintang lima global."</p>
               <button onClick={commonNavProps.onConsultancyClick} className="px-12 py-6 bg-slate-900 text-white font-black uppercase tracking-[0.3em] text-[11px] rounded-[2rem] hover:bg-gold transition-all shadow-2xl">Inquiry Sekarang</button>
             </div>
             <div className="w-full lg:w-[400px] aspect-square bg-white rounded-[4rem] shadow-2xl p-12 flex flex-col justify-center text-center">
                <div className="text-7xl mb-8">📈</div>
                <h4 className="font-serif text-3xl mb-4 text-slate-900">Strategic Audit</h4>
                <p className="text-xs text-slate-400 uppercase font-black leading-relaxed tracking-widest">Optimalisasi margin berbasis data.</p>
             </div>
          </div>
        </section>
      </div>

      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { getCMSData, saveCMSData, CMSData, resetToDefault, Partner } from '../services/dataService';
import { ClassType, CulinaryClass, PortfolioItem, Review } from '../types';

interface Props {
  onExit: () => void;
}

const FileUploader = ({ label, guidance, onUpload }: { label: string, guidance: string, onUpload: (base64: string) => void }) => {
  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => onUpload(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-3">
      <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">{label}</label>
      <div className="flex flex-col gap-2">
        <input 
          type="file" 
          accept="image/*"
          className="w-full text-[10px] text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-[10px] file:font-black file:uppercase file:bg-gold file:text-white hover:file:bg-slate-900 transition-all cursor-pointer"
          onChange={handleFile}
        />
        {guidance && (
          <div className="p-3 bg-blue-50/50 rounded-xl border border-blue-100/50">
            <p className="text-[8px] text-blue-500">{guidance}</p>
          </div>
        )}
      </div>
    </div>
  );
};

const AdminCMS: React.FC<Props> = ({ onExit }) => {
  const [data, setData] = useState<CMSData>(getCMSData());
  const [activeTab, setActiveTab] = useState<'hero' | 'profile' | 'partners' | 'workshops' | 'recorded' | 'portfolio' | 'reviews'>('hero');
  const [isSaved, setIsSaved] = useState(false);

  const handleSave = () => {
    saveCMSData(data);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const updateField = (field: keyof CMSData, value: any) => {
    setData(prev => ({ ...prev, [field]: value }));
  };

  const updateListItem = (field: keyof CMSData, id: string, updates: any) => {
    setData(prev => ({
      ...prev,
      [field]: (prev[field] as any[]).map(item => item.id === id ? { ...item, ...updates } : item)
    }));
  };

  const addItem = (field: keyof CMSData, newItem: any) => {
    setData(prev => ({
      ...prev,
      [field]: [newItem, ...(prev[field] as any[])]
    }));
  };

  const removeItem = (field: keyof CMSData, id: string) => {
    setData(prev => ({
      ...prev,
      [field]: (prev[field] as any[]).filter(item => item.id !== id)
    }));
  };

  const workshops = useMemo(() => {
    const list = data.workshops || [];
    return {
      active: list.filter(ws => !ws.isHistorical),
      historical: list.filter(ws => ws.isHistorical)
    };
  }, [data.workshops]);

  return (
    <div className="min-h-screen bg-stone-50 flex font-sans">
      {/* Sidebar */}
      <div className="w-72 bg-slate-950 text-white flex flex-col shadow-2xl z-20">
        <div className="p-10 border-b border-white/5">
          <h1 className="text-2xl font-serif font-black text-gold uppercase tracking-tighter">Chef Portal</h1>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.3em] mt-2">CMS Management</p>
        </div>

        <nav className="flex-grow p-6 space-y-1">
          {[
            { id: 'hero', label: 'Landing Hero', icon: '✨' },
            { id: 'profile', label: 'Chef Profile', icon: '👤' },
            { id: 'partners', label: 'Partners', icon: '🤝' },
            { id: 'workshops', label: 'Workshops', icon: '🎥' },
            { id: 'recorded', label: 'Academy', icon: '📀' },
            { id: 'portfolio', label: 'Portfolio', icon: '🖼️' },
            { id: 'reviews', label: 'Reviews', icon: '⭐️' },
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${
                activeTab === tab.id 
                  ? 'bg-gold text-white shadow-lg translate-x-2' 
                  : 'text-slate-500 hover:text-white hover:bg-white/5'
              }`}
            >
              <span>{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-white/5 space-y-3">
          <button onClick={resetToDefault} className="w-full py-4 text-[10px] font-black uppercase text-red-400 hover:bg-red-400/10 rounded-xl transition-all">Reset Factory</button>
          <button onClick={onExit} className="w-full py-4 bg-white text-slate-950 text-[10px] font-black uppercase rounded-xl hover:bg-gold transition-all">Exit to Website</button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-grow flex flex-col h-screen overflow-hidden">
        <header className="bg-white/80 backdrop-blur-md border-b border-stone-200 h-24 flex items-center justify-between px-12">
          <h2 className="text-xl font-serif font-black text-slate-900 uppercase tracking-widest">{activeTab}</h2>
          <div className="flex items-center gap-6">
            {isSaved && <span className="text-green-600 text-[10px] font-black uppercase tracking-widest animate-pulse">Saved Successfully</span>}
            <button onClick={handleSave} className="px-10 py-4 bg-slate-900 text-white text-[11px] font-black uppercase rounded-full hover:bg-gold transition-all shadow-xl">Publish Updates</button>
          </div>
        </header>

        <main className="p-12 overflow-y-auto flex-grow">
          <div className="max-w-5xl mx-auto space-y-12">

            {/* HERO TAB */}
            {activeTab === 'hero' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-10 rounded-[3rem] border border-stone-200 space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Hero Main Title</label>
                    <input type="text" className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-4 text-sm font-bold" value={data.heroTitle} onChange={(e) => updateField('heroTitle', e.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Description</label>
                    <textarea className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-4 text-sm h-32" value={data.heroSubtitle} onChange={(e) => updateField('heroSubtitle', e.target.value)} />
                  </div>
                </div>
                <div className="bg-white p-10 rounded-[3rem] border border-stone-200 flex flex-col items-center">
                  <div className="aspect-[3/4] w-48 rounded-3xl overflow-hidden shadow-2xl mb-6">
                    <img src={data.heroImage} className="w-full h-full object-cover" alt="" />
                  </div>
                  <FileUploader label="Update Hero Image" guidance="Portrait 3:4 recommended." onUpload={(b) => updateField('heroImage', b)} />
                </div>
              </div>
            )}

            {/* PROFILE TAB */}
            {activeTab === 'profile' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-10 rounded-[3rem] border border-stone-200 space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Chef Name</label>
                    <input type="text" className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-4 text-sm font-bold" value={data.chefName} onChange={(e) => updateField('chefName', e.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Main Quote</label>
                    <input type="text" className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-4 text-sm italic" value={data.chefBioQuote} onChange={(e) => updateField('chefBioQuote', e.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Biography</label>
                    <textarea className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-4 text-sm h-48" value={data.chefBio} onChange={(e) => updateField('chefBio', e.target.value)} />
                  </div>
                </div>
                <div className="bg-white p-10 rounded-[3rem] border border-stone-200 flex flex-col items-center">
                  <div className="aspect-[4/5] w-48 rounded-3xl overflow-hidden shadow-2xl mb-6">
                    <img src={data.chefProfileImage} className="w-full h-full object-cover" alt="" />
                  </div>
                  <FileUploader label="Update Profile Photo" guidance="Professional portrait." onUpload={(b) => updateField('chefProfileImage', b)} />
                </div>
              </div>
            )}

            {/* PARTNERS TAB */}
            {activeTab === 'partners' && (
              <div className="space-y-8">
                <button onClick={() => addItem('partners', { id: `p-${Date.now()}`, name: 'New Partner', logo: '🏢' })} className="px-6 py-3 bg-slate-900 text-white text-[10px] font-black uppercase rounded-full">+ Add Partner</button>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                  {data.partners.map(p => (
                    <div key={p.id} className="bg-white p-6 rounded-3xl border border-stone-200 flex flex-col items-center gap-4 group">
                      <div className="text-4xl">{p.logo.length < 50 ? p.logo : '🖼️'}</div>
                      <input className="text-center text-[10px] font-black uppercase w-full bg-stone-50 p-2" value={p.name} onChange={(e) => updateListItem('partners', p.id, { name: e.target.value })} />
                      <FileUploader label="Logo" guidance="Small icon." onUpload={(b) => updateListItem('partners', p.id, { logo: b })} />
                      <button onClick={() => removeItem('partners', p.id)} className="text-[8px] text-red-500 uppercase font-black opacity-0 group-hover:opacity-100 transition-opacity">Remove</button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* WORKSHOPS TAB */}
            {activeTab === 'workshops' && (
              <div className="space-y-12">
                <div className="flex justify-between items-center">
                  <h3 className="text-sm font-black uppercase tracking-widest text-gold">Active Workshops</h3>
                  <button onClick={() => addItem('workshops', { id: `ws-${Date.now()}`, title: 'New Workshop Batch', description: 'Intensive session...', price: 1500000, location: 'Zoom / Offline', image: 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?q=80&w=800', type: ClassType.LIVE, duration: '4 Hours', level: 'Professional', date: new Date(Date.now() + 86400000 * 7).toISOString().slice(0, 16), isHistorical: false })} className="px-6 py-3 bg-slate-900 text-white text-[10px] font-black uppercase rounded-full">+ Add New Batch</button>
                </div>
                <div className="space-y-6">
                  {workshops.active.map(ws => (
                    <div key={ws.id} className="bg-white p-8 rounded-[3rem] border border-stone-200 flex flex-col md:flex-row gap-8">
                      <div className="w-40 h-40 rounded-3xl overflow-hidden bg-stone-100 flex-shrink-0"><img src={ws.image} className="w-full h-full object-cover" alt="" /></div>
                      <div className="flex-grow space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <input className="text-lg font-serif font-black bg-stone-50 rounded p-2" value={ws.title} onChange={(e) => updateListItem('workshops', ws.id, { title: e.target.value })} />
                          <input type="datetime-local" className="text-xs bg-stone-50 rounded p-2" value={ws.date ? ws.date.slice(0, 16) : ''} onChange={(e) => updateListItem('workshops', ws.id, { date: e.target.value })} />
                        </div>
                        <div className="grid grid-cols-3 gap-4">
                           <input type="number" placeholder="Price" className="text-xs bg-stone-50 rounded p-2" value={ws.price || 0} onChange={(e) => updateListItem('workshops', ws.id, { price: Number(e.target.value) })} />
                           <input placeholder="Location" className="text-xs bg-stone-50 rounded p-2" value={ws.location || ''} onChange={(e) => updateListItem('workshops', ws.id, { location: e.target.value })} />
                           <button onClick={() => updateListItem('workshops', ws.id, { isHistorical: true })} className="text-[9px] font-black uppercase text-gold hover:underline">Move to Historical</button>
                        </div>
                        <FileUploader label="" guidance="" onUpload={(b) => updateListItem('workshops', ws.id, { image: b })} />
                        <button onClick={() => removeItem('workshops', ws.id)} className="text-[9px] font-black uppercase text-red-500">Remove</button>
                      </div>
                    </div>
                  ))}
                  {workshops.active.length === 0 && <p className="text-slate-400 text-center py-10 italic">No active workshops. Add one to show on website.</p>}
                </div>
                <div className="pt-12 border-t border-stone-200">
                  <h3 className="text-sm font-black uppercase tracking-widest text-slate-400 mb-6">Historical Archives</h3>
                  <div className="space-y-6">
                    {workshops.historical.map(ws => (
                      <div key={ws.id} className="bg-white/60 p-6 rounded-[2.5rem] border border-stone-100 flex gap-6 grayscale hover:grayscale-0 transition-all">
                        <div className="w-24 h-24 rounded-2xl overflow-hidden flex-shrink-0"><img src={ws.image} className="w-full h-full object-cover" alt="" /></div>
                        <div className="flex-grow">
                          <h4 className="font-serif font-bold">{ws.title}</h4>
                          <p className="text-[10px] text-slate-400">{ws.location} • {ws.realAttendance || 0} Alumni</p>
                          <div className="mt-2 flex gap-4">
                             <button onClick={() => updateListItem('workshops', ws.id, { isHistorical: false })} className="text-[8px] font-black uppercase text-blue-500">Restore to Active</button>
                             <button onClick={() => removeItem('workshops', ws.id)} className="text-[8px] font-black uppercase text-red-500">Delete Permanently</button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* ACADEMY TAB */}
            {activeTab === 'recorded' && (
              <div className="space-y-8">
                <button onClick={() => addItem('recordedClasses', { id: `rc-${Date.now()}`, title: 'New Recorded Class', description: 'Video module description...', price: 499000, image: 'https://images.unsplash.com/photo-1606787366850-de6330128bfc?q=80&w=800', type: ClassType.RECORDED, duration: '5 Modules', level: 'Beginner', soldCount: 0 })} className="px-6 py-3 bg-slate-900 text-white text-[10px] font-black uppercase rounded-full">+ Add Video Course</button>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {data.recordedClasses.map(rc => (
                    <div key={rc.id} className="bg-white p-8 rounded-[3rem] border border-stone-200 flex flex-col gap-6">
                      <div className="aspect-video rounded-2xl overflow-hidden bg-stone-100"><img src={rc.image} className="w-full h-full object-cover" alt="" /></div>
                      <div className="space-y-4">
                        <input className="w-full font-serif font-black text-lg bg-stone-50 p-2" value={rc.title} onChange={(e) => updateListItem('recordedClasses', rc.id, { title: e.target.value })} />
                        <textarea className="w-full text-xs bg-stone-50 p-2 h-20" value={rc.description} onChange={(e) => updateListItem('recordedClasses', rc.id, { description: e.target.value })} />
                        <div className="grid grid-cols-2 gap-4">
                          <input type="number" className="text-xs bg-stone-50 p-2" value={rc.price} onChange={(e) => updateListItem('recordedClasses', rc.id, { price: Number(e.target.value) })} />
                          <input className="text-xs bg-stone-50 p-2" value={rc.duration} onChange={(e) => updateListItem('recordedClasses', rc.id, { duration: e.target.value })} />
                        </div>
                        <FileUploader label="Thumbnail" guidance="16:9 Aspect Ratio." onUpload={(b) => updateListItem('recordedClasses', rc.id, { image: b })} />
                        <button onClick={() => removeItem('recordedClasses', rc.id)} className="text-red-500 text-[10px] font-black uppercase">Remove Class</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* PORTFOLIO TAB */}
            {activeTab === 'portfolio' && (
              <div className="space-y-8">
                <button onClick={() => addItem('portfolio', { id: `p-${Date.now()}`, title: 'New Project', category: 'Hotel', image: 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?q=80&w=800', aiPrompt: '' })} className="px-6 py-3 bg-slate-900 text-white text-[10px] font-black uppercase rounded-full">+ Add Portfolio</button>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                  {data.portfolio.map(p => (
                    <div key={p.id} className="bg-white p-6 rounded-3xl border border-stone-200 space-y-4">
                      <div className="aspect-square rounded-2xl overflow-hidden"><img src={p.image} className="w-full h-full object-cover" alt="" /></div>
                      <input className="w-full text-xs font-bold bg-stone-50 p-2" value={p.title} onChange={(e) => updateListItem('portfolio', p.id, { title: e.target.value })} />
                      <FileUploader label="" guidance="" onUpload={(b) => updateListItem('portfolio', p.id, { image: b })} />
                      <button onClick={() => removeItem('portfolio', p.id)} className="text-red-500 text-[8px] uppercase font-black">Remove</button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* REVIEWS TAB */}
            {activeTab === 'reviews' && (
              <div className="space-y-8">
                <button onClick={() => addItem('reviews', { id: `r-${Date.now()}`, name: 'Reviewer Name', role: 'Executive Chef', comment: 'Amazing session...', avatar: 'https://i.pravatar.cc/150?u=new' })} className="px-6 py-3 bg-slate-900 text-white text-[10px] font-black uppercase rounded-full">+ Add Review</button>
                <div className="space-y-6">
                  {data.reviews.map(r => (
                    <div key={r.id} className="bg-white p-8 rounded-[3rem] border border-stone-200 flex gap-8 items-start">
                      <div className="w-20 h-20 rounded-2xl overflow-hidden flex-shrink-0"><img src={r.avatar} className="w-full h-full object-cover" alt="" /></div>
                      <div className="flex-grow space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <input className="font-black text-sm uppercase bg-stone-50 p-2" value={r.name} onChange={(e) => updateListItem('reviews', r.id, { name: e.target.value })} />
                          <input className="text-xs text-gold uppercase font-black bg-stone-50 p-2" value={r.role} onChange={(e) => updateListItem('reviews', r.id, { role: e.target.value })} />
                        </div>
                        <textarea className="w-full text-xs italic bg-stone-50 p-2 h-24" value={r.comment} onChange={(e) => updateListItem('reviews', r.id, { comment: e.target.value })} />
                        <FileUploader label="Avatar" guidance="Square ratio." onUpload={(b) => updateListItem('reviews', r.id, { avatar: b })} />
                        <button onClick={() => removeItem('reviews', r.id)} className="text-red-500 text-[8px] uppercase font-black">Delete Review</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

          </div>
        </main>
      </div>
    </div>
  );
};

export default AdminCMS;

