// Fungsi inisialisasi tabel jika belum ada
async function ensureTable() {
  try {
    await sql`
      CREATE TABLE IF NOT EXISTS chef_cms_data (
        id SERIAL PRIMARY KEY,
        config JSONB NOT NULL,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );
    `;
  } catch (e) {
    console.error("Failed to ensure table exists", e);
  }
}

export const getCMSData = async (): Promise<CMSData> => {
  try {
    await ensureTable();
    const { rows } = await sql`SELECT config FROM chef_cms_data ORDER BY id DESC LIMIT 1;`;
    if (rows && rows.length > 0) {
      return rows[0].config as CMSData;
    }
  } catch (e) {
    console.warn("Postgres fetch failed, using fallback defaults", e);
  }
  return DEFAULT_DATA;
};

export const saveCMSData = async (data: CMSData) => {
  try {
    await ensureTable();
    // Simpan sebagai row baru (histori) atau update
    await sql`
      INSERT INTO chef_cms_data (config) 
      VALUES (${JSON.stringify(data) as any})
    `;
    console.log("Data saved to Vercel Postgres");
  } catch (e) {
    console.error("Failed to save to Postgres", e);
    // Fallback ke localstorage jika DB mati
    localStorage.setItem('CHEF_ANTON_BACKUP', JSON.stringify(data));
  }
};

import { put } from '@vercel/blob';

/**
 * Mengunggah file gambar ke Vercel Blob storage.
 * @param file File objek dari input form atau base64 string
 * @param filename Nama file untuk identifikasi
 */
export const uploadImageToBlob = async (file: File | string, filename: string): Promise<string> => {
  try {
    // Jika file adalah base64 (dari FileReader), kita konversi ke Blob
    let fileToUpload: File | Blob;
    if (typeof file === 'string' && file.startsWith('data:')) {
      const response = await fetch(file);
      fileToUpload = await response.blob();
    } else {
      fileToUpload = file as File;
    }

    const blob = await put(`chef-anton/${Date.now()}-${filename}`, fileToUpload, {
      access: 'public',
      contentType: 'image/jpeg',
    });

    return blob.url;
  } catch (error) {
    console.error("Vercel Blob Upload Error:", error);
    // Fallback jika upload gagal, kembalikan base64 agar tetap bisa tampil sementara
    return typeof file === 'string' ? file : "";
  }
};

