/**
 * Ensures the database table exists for CMS data.
 */
async function initDatabase() {
  try {
    await sql`
      CREATE TABLE IF NOT EXISTS chef_branding_cms (
        id SERIAL PRIMARY KEY,
        config JSONB NOT NULL,
        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `;
  } catch (err) {
    console.error("Postgres init error:", err);
  }
}

/**
 * Fetches the latest CMS configuration from Vercel Postgres.
 */
export const getCMSData = async (): Promise<CMSData> => {
  await initDatabase();
  try {
    const { rows } = await sql`SELECT config FROM chef_branding_cms ORDER BY id DESC LIMIT 1;`;
    if (rows && rows.length > 0) {
      const data = rows[0].config as CMSData;
      if (data.version === DATA_VERSION) {
        return data;
      }
    }
  } catch (err) {
    console.warn("Could not fetch from Postgres, returning defaults", err);
  }
  return DEFAULT_DATA;
};

/**
 * Saves CMS configuration to Vercel Postgres.
 */
export const saveCMSData = async (data: CMSData) => {
  try {
    const jsonConfig = JSON.stringify({ ...data, version: DATA_VERSION });
    await sql`
      INSERT INTO chef_branding_cms (config)
      VALUES (${jsonConfig as any});
    `;
    console.log("CMS Data successfully persisted to Vercel Postgres");
  } catch (err) {
    console.error("Postgres save error:", err);
    throw err;
  }
};

/**
 * Resets the application data.
 */
export const resetToDefault = async () => {
  try {
    await sql`DELETE FROM chef_branding_cms;`;
    window.location.reload();
  } catch (err) {
    console.error("Postgres reset error:", err);
  }
};

import { put } from '@vercel/blob';
import { GoogleGenAI } from "@google/genai";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function callWithRetry<T>(fn: () => Promise<T>, retries = 2, delay = 2000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    const isRateLimit = error?.message?.includes('429') || error?.status === 429 || error?.message?.includes('RESOURCE_EXHAUSTED');
    if (retries > 0 && isRateLimit) {
      console.warn(`Rate limit hit, retrying in ${delay}ms...`);
      await sleep(delay);
      return callWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

/**
 * Uploads an image file or base64 string to Vercel Blob storage.
 */
export const uploadImageToBlob = async (file: File | string, filename: string): Promise<string> => {
  try {
    let dataToUpload: File | Blob;

    if (typeof file === 'string' && file.startsWith('data:')) {
      const response = await fetch(file);
      dataToUpload = await response.blob();
    } else if (file instanceof File) {
      dataToUpload = file;
    } else {
      throw new Error("Invalid file format for upload");
    }

    const { url } = await put(`chef-anton/${Date.now()}-${filename}`, dataToUpload, {
      access: 'public',
      contentType: 'image/jpeg',
    });

    return url;
  } catch (error) {
    console.error("Vercel Blob Upload Error:", error);
    // Return the original base64 as fallback if upload fails
    return typeof file === 'string' ? file : "";
  }
};

export const generateChefImage = async (context: string): Promise<string> => {
  return callWithRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const basePrompt = `
      PHOTOREALISTIC 8K. Close-up portrait of a professional Indonesian male Executive Chef, 
      middle-aged, charismatic and professional friendly smile. 
      UNIFORM: Pristine white professional chef jacket with distinctive orange batik patterns on the collar and cuffs. 
      HAT: Wearing a very tall, stiff, white professional chef hat (toque blanche). 
      SETTING: ${context}. 
      LIGHTING: Cinematic golden hour lighting, luxury hotel kitchen bokeh background. 
      Sharp focus, highly detailed skin texture, professional culinary photography style.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: basePrompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: "3:4"
        },
      },
    });

    const candidate = response.candidates?.[0];
    if (candidate?.content?.parts) {
      for (const part of candidate.content.parts) {
        if (part.inlineData?.data) {
          const base64 = `data:image/png;base64,${part.inlineData.data}`;
          // Optionally upload generated images to blob for permanence
          return await uploadImageToBlob(base64, 'generated-chef.png');
        }
      }
    }
    throw new Error("No image data found in response");
  }).catch(error => {
    console.warn("Chef image generation failed after retries, using fallback.", error);
    return "https://images.unsplash.com/photo-1583394293214-28ded15ee548?q=80&w=1000&auto=format&fit=crop";
  });
};

