          </div>

          {!ws.isHistorical ? (
            // ACTIVE WORKSHOP FIELDS
            <>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Price (IDR)</label>
                <input className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-sm" type="number" value={ws.price} onChange={(e) => updateListItem('workshops', ws.id, { price: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Price Before Discount</label>
                <input className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-sm" type="number" value={ws.priceBeforeDiscount || 0} onChange={(e) => updateListItem('workshops', ws.id, { priceBeforeDiscount: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Duration (e.g. 6 Jam Intensif)</label>
                <input className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-sm" value={ws.duration} onChange={(e) => updateListItem('workshops', ws.id, { duration: e.target.value })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Slots Available</label>
                <input className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-sm" type="number" value={ws.slots || 0} onChange={(e) => updateListItem('workshops', ws.id, { slots: Number(e.target.value) })} />
              </div>
              <div className="col-span-2 space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Curriculum (Pemisah Baris Baru)</label>
                <textarea className="w-full bg-stone-50 border border-stone-100 p-4 rounded-xl text-xs h-32 leading-relaxed" value={ws.curriculum?.join('\n')} onChange={(e) => updateListItem('workshops', ws.id, { curriculum: e.target.value.split('\n') })} />
              </div>
            </>
          ) : (
            // HISTORICAL WORKSHOP FIELDS
            <>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Lokasi Pelaksanaan (e.g. Jakarta Session)</label>
                <input className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-sm" value={ws.location} onChange={(e) => updateListItem('workshops', ws.id, { location: e.target.value })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Tanggal Tampil (e.g. 20 Oktober 2024)</label>
                <input className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-sm" value={ws.displayDate} onChange={(e) => updateListItem('workshops', ws.id, { displayDate: e.target.value })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Total Alumni (Kehadiran)</label>
                <input className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-sm" type="number" value={ws.realAttendance || 0} onChange={(e) => updateListItem('workshops', ws.id, { realAttendance: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Level Masterclass</label>
                <select className="w-full bg-stone-50 border border-stone-100 p-3 rounded-xl text-[10px] font-black uppercase" value={ws.level} onChange={(e) => updateListItem('workshops', ws.id, { level: e.target.value })}>
                  <option>Beginner</option>
                  <option>Professional</option>
                  <option>Executive</option>
