              </div>
              <div className="col-span-2 space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Deskripsi Singkat (Short Legacy Pitch)</label>
                <textarea className="w-full bg-stone-50 border border-stone-100 p-4 rounded-xl text-xs h-24 italic" value={ws.description} onChange={(e) => updateListItem('workshops', ws.id, { description: e.target.value })} />
              </div>
            </>
          )}
        </div>
        <div className="flex flex-wrap items-center gap-6 pt-4 border-t border-stone-100">
          <FileUploader label="Update Poster" sizeGuidance="Portrait 3:4" isUploading={uploadingField === `workshops:${ws.id}`} onUpload={(b) => handleImageUpload(`workshops:${ws.id}`, b, 'workshop.jpg')} />
