           <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.4em] mt-3 italic">Management Console</p>
        </div>

        <nav className="flex-grow p-8 space-y-2 overflow-y-auto">
          {navItems.map(tab => (
            <button 
              key={tab.id} 
              onClick={() => {setActiveTab(tab.id as any); setIsSidebarOpen(false);}} 
              className={`w-full flex items-center gap-5 px-7 py-5 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-300 relative ${activeTab === tab.id ? 'bg-gold text-white shadow-2xl translate-x-2' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}
