      <div className="flex-grow flex flex-col h-screen overflow-hidden">
        <header className="bg-white/90 backdrop-blur-xl border-b border-stone-100 h-28 flex items-center justify-between px-12 shrink-0 sticky top-0 z-40 shadow-sm">
          <div className="flex items-center gap-6">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-900 p-3 bg-stone-100 rounded-2xl">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
             </button>
             <div>
               <h2 className="text-[11px] font-black text-gold uppercase tracking-[0.4em]">Configuration Mode</h2>
               <p className="text-2xl font-serif font-black text-slate-900 uppercase tracking-widest mt-0.5">{activeTab}</p>
             </div>
          </div>

          <div className="flex items-center gap-6">
            <button 
              onClick={handleSave} 
              disabled={isSaving || uploadingField !== null} 
              className={`group flex items-center gap-4 px-10 py-5 bg-slate-950 text-white text-[11px] font-black uppercase tracking-[0.2em] rounded-2xl hover:bg-gold transition-all shadow-xl disabled:opacity-50`}
            >
              {isSaving ? "Syncing Changes..." : uploadingField ? "Uploading..." : "Publish Updates"}
            </button>
          </div>
        </header>

        <main className="p-12 overflow-y-auto flex-grow">
           {isSaved && (
             <div className="mb-10 p-8 bg-green-500 text-white rounded-[2.5rem] text-center font-black uppercase text-[11px] tracking-[0.4em] shadow-2xl animate-in zoom-in-95">
               Data synchronized successfully!
             </div>
           )}

           <div className="max-w-7xl mx-auto pb-20">
             {activeTab === 'hero' && (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                   <div className="lg:col-span-7 bg-white p-12 rounded-[4rem] border border-stone-200 space-y-10">
                     <SectionHeader title="Hero Branding" />
                     <InputWrapper label="Landing Title">
                       <input className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-6 py-5 text-2xl font-serif font-black focus:bg-white outline-none" value={data?.heroTitle} onChange={(e) => updateField('heroTitle', e.target.value)} />
