  .gold-gradient {
    background: linear-gradient(135deg, #D4AF37 0%, #B8860B 100%);
  }

  .gold-soft-gradient {
    background: linear-gradient(135deg, #FFFDF5 0%, #FFFFFF 100%);
  }

  .dot-pattern-gold {
    background-image: radial-gradient(#D4AF37 0.5px, transparent 0.5px);
    background-size: 24px 24px;
    opacity: 0.15;
