    if (!data) return;

    // Feedback Instan: Tampilkan loading state
    setUploadingField(field);

    // Gunakan preview sementara dari file asli untuk responsivitas UI
    const initialPreviewUrl = URL.createObjectURL(file);
    setLocalPreviews(prev => ({ ...prev, [field]: initialPreviewUrl }));

    try {
      // Jalankan upload (di dalamnya ada kompresi otomatis & cek limit 4MB)
      const url = await uploadImageToBlob(file, filename);

      // Update state data dengan URL permanen dari cloud
      if (field === 'heroImage' || field === 'chefProfileImage') {
        updateField(field as keyof CMSData, url);
      } else if (field.includes(':')) {
        const [listKey, id] = field.split(':');
        const list = [...(data[listKey as keyof CMSData] as any[])];
