      // Update preview lokal dengan URL cloud (opsional, tapi bagus untuk konsistensi)
      setLocalPreviews(prev => ({ ...prev, [field]: url }));

    } catch (err: any) {
      alert(err.message || "Gagal mengunggah gambar. Pastikan file valid.");
