/**
 * Optimized Image Compression
 * - Direct resize to 1080px max-width
 * - Single pass 0.7 quality export
 * - 10s timeout protection
 */
const compressImage = (file: File, timeoutMs = 10000): Promise<{ base64: string, type: string }> => {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error("Timeout: Proses kompresi gambar terlalu lama (lebih dari 10 detik)."));
    }, timeoutMs);

    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        clearTimeout(timer);
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_WIDTH = 1080; // Fast resize target

        if (width > MAX_WIDTH) {
          height = Math.round((MAX_WIDTH / width) * height);
          width = MAX_WIDTH;
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return reject(new Error("Gagal menginisialisasi canvas context"));

        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'medium'; // Balance speed/quality

        ctx.drawImage(img, 0, 0, width, height);

        // Single pass: Compress directly to JPEG with 0.7 quality
        const dataUrl = canvas.toDataURL('image/jpeg', 0.7);

        // Final size check for payload safety
        const stringLength = dataUrl.length - 'data:image/jpeg;base64,'.length;
        const sizeInMb = (4 * Math.ceil(stringLength / 3) * 0.5624896334383812) / (1024 * 1024);

        if (sizeInMb > 4) {
          return reject(new Error("File terlalu besar bahkan setelah kompresi. Harap gunakan foto lain."));
        }

        resolve({ base64: dataUrl, type: 'image/jpeg' });
      };
      img.onerror = () => {
        clearTimeout(timer);
        reject(new Error("Gagal memproses file gambar."));
      };
    };
    reader.onerror = () => {
      clearTimeout(timer);
      reject(new Error("Gagal membaca file."));
    };
  });
};

