           <div className="mt-24 pt-12 border-t border-stone-200 text-center">
             <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.5em]">Elite Culinary Branding System v7.8 • Premium Enterprise Access</p>
           </div>
