  const { id } = useParams();
  const navigate = useNavigate();

  const selectedWorkshop = useMemo(() => {
    const all = [...workshops, ...historicalWorkshops];
    return all.find(w => String(w.id) === String(id)) || null;
  }, [workshops, historicalWorkshops, id]);

  return (
    <LiveWorkshopDetail 
      workshop={selectedWorkshop} 
      historicalWorkshops={historicalWorkshops}
      reviews={reviews}
      onBack={() => navigate('/')}
      onViewWorkshop={(wsId) => navigate(`/workshop/${wsId}`)}
