const App: React.FC = () => {
  const [cmsData, setCmsData] = useState<CMSData | null>(null);
  const [loading, setLoading] = useState(true);
  const [routeTransitioning, setRouteTransitioning] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      try {
        const data = await getCMSData();
        setCmsData(data);
      } catch (err) {
        setCmsData(DEFAULT_DATA);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  // Handle route transition loading effect
  useEffect(() => {
    setRouteTransitioning(true);
    const timer = setTimeout(() => {
      setRouteTransitioning(false);
    }, 1000); // 1s elegant transition
    return () => clearTimeout(timer);
  }, [location.pathname]);

  const workshopsData = useMemo(() => {
    if (!cmsData) return { active: [], historical: [] };
    const now = new Date();
    const list = cmsData.workshops || [];
    const processed = [...list].map(ws => {
      if (ws.date && !ws.isHistorical) {
        const wsDate = new Date(ws.date);
        if (wsDate < now) return { ...ws, isHistorical: true };
      }
      return ws;
    });

    return {
      active: processed.filter(ws => !ws.isHistorical),
      historical: processed.filter(ws => ws.isHistorical)
    };
  }, [cmsData]);

  const categorizedReviews = useMemo(() => {
    const reviews = cmsData?.reviews || [];
    return {
      all: reviews,
      workshop: reviews.filter(r => r.category === 'Live Workshop'),
      recorded: reviews.filter(r => r.category === 'Kelas Rekaman'),
      consultancy: reviews.filter(r => r.category === 'Private Consultancy')
    };
  }, [cmsData]);

  if (loading && !cmsData) return <LoadingScreen />;

  const finalCmsData = cmsData || DEFAULT_DATA;

  return (
    <div className="min-h-screen bg-white selection:bg-gold/30">
      <ScrollToTop />
      {routeTransitioning && <LoadingScreen />}

      <Navbar 
        onHomeClick={() => navigate('/')}
        onWorkshopClick={() => {
           if (workshopsData.active.length > 0) navigate(`/workshop/${workshopsData.active[0].id}`);
           else navigate('/#live-workshops');
        }}
        onRecordedClick={() => navigate('/academy')}
        onConsultancyClick={() => navigate('/consultancy')}
      />

      <Routes>
        <Route path="/" element={<Home finalCmsData={finalCmsData} workshopsData={workshopsData} categorizedReviews={categorizedReviews} />} />
        <Route 
          path="/workshop/:id" 
          element={
            <WorkshopDetailWrapper 
              workshops={workshopsData.active} 
              historicalWorkshops={workshopsData.historical} 
              reviews={categorizedReviews.workshop} 
            />
          } 
        />
        <Route 
          path="/academy" 
          element={
            <RecordedClassDetail 
              onBack={() => navigate('/')} 
              reviews={categorizedReviews.recorded} 
              recordedClasses={finalCmsData.recordedClasses} 
            />
          } 
        />
        <Route 
          path="/consultancy" 
          element={
            <ConsultancyDetail 
              onBack={() => navigate('/')} 
              reviews={categorizedReviews.consultancy} 
              partners={finalCmsData.partners} 
            />
          } 
        />
      </Routes>

      <Footer data={finalCmsData} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { NAV_ITEMS } from '../constants';

interface NavbarProps {
  onHomeClick?: () => void;
  onWorkshopClick?: () => void;
  onRecordedClick?: () => void;
  onConsultancyClick?: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ onHomeClick, onWorkshopClick, onRecordedClick, onConsultancyClick }) => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();

  const handleLinkClick = (e: React.MouseEvent, item: any) => {
    if (item.label === 'Home' && onHomeClick) {
      e.preventDefault();
      onHomeClick();
    } else if (item.label === 'Live Workshop' && onWorkshopClick) {
      e.preventDefault();
      onWorkshopClick();
    } else if (item.label === 'Kelas Rekaman' && onRecordedClick) {
      e.preventDefault();
      onRecordedClick();
    } else if (item.label === 'Private Konsultasi' && onConsultancyClick) {
      e.preventDefault();
      onConsultancyClick();
    }
    setIsOpen(false);
  };

  return (
    <nav className="fixed w-full z-50 bg-white/90 backdrop-blur-md border-b border-stone-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20 items-center">
          <Link to="/" className="flex-shrink-0" onClick={() => onHomeClick?.()}>
            <span className="text-xl md:text-2xl font-black tracking-tighter text-slate-900 font-serif uppercase">
              CHEF<span className="text-gold ml-1">ANTON PRADIPTA</span>
            </span>
          </Link>

          <div className="hidden lg:flex space-x-12">
            {NAV_ITEMS.map((item) => {
              // Map navigation item logic to paths
              let path = '/';
              if (item.label === 'Live Workshop') path = '/workshop/active'; // Placeholder, actual logic handles via click
              if (item.label === 'Kelas Rekaman') path = '/academy';
              if (item.label === 'Private Konsultasi') path = '/consultancy';

              return (
                <a
                  key={item.label}
                  href={item.href}
                  className={`text-[10px] font-black uppercase tracking-[0.2em] transition-colors duration-200 ${
                    location.pathname === path ? 'text-gold' : 'text-slate-500 hover:text-gold'
                  }`}
                  onClick={(e) => handleLinkClick(e, item)}
                >
                  {item.label}
                </a>
              );
            })}
          </div>

          <div className="lg:hidden">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-slate-600 p-2"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="lg:hidden bg-white border-t border-slate-100 shadow-2xl">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {NAV_ITEMS.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className="block px-3 py-4 text-sm font-bold text-slate-600 hover:bg-stone-50 hover:text-gold border-b border-stone-50"
                onClick={(e) => handleLinkClick(e, item)}
              >
                {item.label}
              </a>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

