    return data.reviews.filter(r => r.category === 'Live Workshop');
  }, [data.reviews]);

  if (!workshop && id !== 'active') {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-12 text-center">
        <h2 className="text-4xl font-serif mb-6">Sesi Tidak Ditemukan</h2>
        <button onClick={() => navigate('/')} className="px-8 py-4 bg-slate-950 text-white text-[10px] font-black uppercase tracking-widest rounded-full">Kembali Ke Beranda</button>
      </div>
    );
  }

  return (
    <LiveWorkshopDetail 
      workshop={workshop} 
      historicalWorkshops={historical}
      reviews={reviews}
      onBack={() => navigate('/')}
      onViewWorkshop={(wsId) => navigate(`/workshop/${wsId}`)}
    />
  );
};

// --- App Root ---

const AppContent = () => {
  const [data, setData] = useState<CMSData | null>(null);
  const [loading, setLoading] = useState(true);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const init = async () => {
      setLoading(true);
      try {
        const d = await getCMSData();
        setData(d);
      } catch (err) {
        setData(DEFAULT_DATA);
      } finally {
        setLoading(false);
      }
    };
    init();
  }, []);

  // Handle CMS view separately
  if (location.pathname === '/portal-chef') {
    return <AdminCMS onExit={() => navigate('/')} />;
  }

  if (loading && !data) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center">
        <div className="w-16 h-16 border-4 border-gold border-t-transparent rounded-full animate-spin mb-6"></div>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 italic">Chef Anton is preparing the kitchen...</p>
      </div>
    );
  }

  const finalData = data || DEFAULT_DATA;

  return (
    <div className="min-h-screen bg-white selection:bg-gold/30">
      <ScrollToTop />
      <TopLineProgressBar />

      <Navbar 
        onHomeClick={() => navigate('/')}
        onWorkshopClick={() => {
          const active = finalData.workshops.find(w => !w.isHistorical);
          if (active) navigate(`/workshop/${active.id}`);
          else navigate('/#live-workshops');
        }}
        onRecordedClick={() => navigate('/academy')}
        onConsultancyClick={() => navigate('/consultancy')}
      />

      <Routes>
        <Route path="/" element={<HomeView data={finalData} />} />
        <Route path="/workshop/:id" element={<WorkshopDetailView data={finalData} />} />
        <Route path="/academy" element={<RecordedClassDetail onBack={() => navigate('/')} reviews={finalData.reviews.filter(r => r.category === 'Kelas Rekaman')} recordedClasses={finalData.recordedClasses} />} />
        <Route path="/consultancy" element={<ConsultancyDetail onBack={() => navigate('/')} reviews={finalData.reviews.filter(r => r.category === 'Private Consultancy')} partners={finalData.partners} />} />
      </Routes>

      <Footer data={finalData} />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
};

export default App;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { NAV_ITEMS } from '../constants';

interface NavbarProps {
  onHomeClick?: () => void;
  onWorkshopClick?: () => void;
  onRecordedClick?: () => void;
  onConsultancyClick?: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ onHomeClick, onWorkshopClick, onRecordedClick, onConsultancyClick }) => {
  const [isOpen, setIsOpen] = useState(false);
  const navigate = useNavigate();

  const handleNavClick = (e: React.MouseEvent, item: any) => {
    e.preventDefault();
    setIsOpen(false);

    if (item.label === 'Home') onHomeClick?.();
    else if (item.label === 'Live Workshop') onWorkshopClick?.();
    else if (item.label === 'Kelas Rekaman') onRecordedClick?.();
    else if (item.label === 'Private Konsultasi') onConsultancyClick?.();
  };

  return (
    <nav className="fixed w-full z-[5000] bg-white/90 backdrop-blur-md border-b border-stone-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20 items-center">
          <div className="flex-shrink-0 cursor-pointer" onClick={() => navigate('/')}>
            <span className="text-xl md:text-2xl font-black tracking-tighter text-slate-900 font-serif uppercase">
              CHEF<span className="text-gold ml-1">ANTON PRADIPTA</span>
            </span>
          </div>

          <div className="hidden lg:flex space-x-12">
            {NAV_ITEMS.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 hover:text-gold transition-colors duration-200"
                onClick={(e) => handleNavClick(e, item)}
              >
                {item.label}
              </a>
            ))}
          </div>

          <div className="lg:hidden">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-slate-600 p-2"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="lg:hidden bg-white border-t border-slate-100 shadow-2xl">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {NAV_ITEMS.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className="block px-3 py-4 text-sm font-bold text-slate-600 hover:bg-stone-50 hover:text-gold border-b border-stone-50"
                onClick={(e) => handleNavClick(e, item)}
              >
                {item.label}
              </a>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

